"use client";

// shadcn/ui-style primitives (cva + cn, same API shape). They can be swapped for
// components generated by `npx shadcn add ...` without changing page code.

import { cva, type VariantProps } from "class-variance-authority";
import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
import { X } from "lucide-react";
import { forwardRef, useEffect, type ButtonHTMLAttributes, type HTMLAttributes, type InputHTMLAttributes, type ReactNode, type SelectHTMLAttributes, type TextareaHTMLAttributes } from "react";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 rounded-lg font-semibold transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-500/40 disabled:pointer-events-none disabled:opacity-50 whitespace-nowrap [&_svg]:size-4 [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        primary: "bg-navy-900 text-white hover:bg-navy-800",
        brand: "bg-brand-600 text-white hover:bg-brand-700",
        teal: "bg-teal-600 text-white hover:bg-teal-700",
        outline: "border border-slate-300 bg-white text-slate-700 hover:bg-slate-50",
        ghost: "text-slate-600 hover:bg-slate-100",
        danger: "bg-red-600 text-white hover:bg-red-700",
        dangerOutline: "border border-red-300 bg-white text-red-600 hover:bg-red-50",
        success: "bg-emerald-600 text-white hover:bg-emerald-700",
        warning: "bg-orange-500 text-white hover:bg-orange-600",
      },
      size: { sm: "h-8 px-3 text-xs", md: "h-10 px-4 text-sm", lg: "h-12 px-5 text-base", icon: "h-9 w-9" },
    },
    defaultVariants: { variant: "primary", size: "md" },
  },
);

export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement>, VariantProps<typeof buttonVariants> {}
export const Button = forwardRef<HTMLButtonElement, ButtonProps>(({ className, variant, size, type = "button", ...props }, ref) => (
  <button ref={ref} type={type} className={cn(buttonVariants({ variant, size }), className)} {...props} />
));
Button.displayName = "Button";

export function Card({ className, ...p }: HTMLAttributes<HTMLDivElement>) {
  return <div className={cn("card", className)} {...p} />;
}
export function CardHeader({ title, icon, action, className, subtitle }: { title: ReactNode; icon?: ReactNode; action?: ReactNode; className?: string; subtitle?: ReactNode }) {
  return (
    <div className={cn("flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 px-5 py-3.5", className)}>
      <div className="flex min-w-0 items-center gap-2.5">
        {icon && <span className="text-brand-600 [&_svg]:size-5">{icon}</span>}
        <div className="min-w-0">
          <h2 className="truncate text-[15px] font-bold text-navy-900">{title}</h2>
          {subtitle && <p className="text-xs text-slate-500">{subtitle}</p>}
        </div>
      </div>
      {action}
    </div>
  );
}

const badgeVariants = cva("inline-flex items-center gap-1 rounded-md border px-2 py-0.5 text-xs font-semibold whitespace-nowrap [&_svg]:size-3.5", {
  variants: {
    tone: {
      green: "border-emerald-200 bg-emerald-50 text-emerald-700",
      amber: "border-amber-200 bg-amber-50 text-amber-700",
      orange: "border-orange-200 bg-orange-50 text-orange-700",
      red: "border-red-200 bg-red-50 text-red-700",
      blue: "border-brand-100 bg-brand-50 text-brand-700",
      teal: "border-teal-100 bg-teal-50 text-teal-700",
      gray: "border-slate-200 bg-slate-50 text-slate-600",
      purple: "border-violet-200 bg-violet-50 text-violet-700",
      navy: "border-navy-900 bg-navy-900 text-white",
    },
  },
  defaultVariants: { tone: "gray" },
});
export type Tone = NonNullable<VariantProps<typeof badgeVariants>["tone"]>;
export function Badge({ tone, className, ...p }: HTMLAttributes<HTMLSpanElement> & { tone?: Tone }) {
  return <span className={cn(badgeVariants({ tone }), className)} {...p} />;
}

export function Label({ children, required, htmlFor, className }: { children: ReactNode; required?: boolean; htmlFor?: string; className?: string }) {
  return (
    <label htmlFor={htmlFor} className={cn("mb-1.5 block text-sm font-semibold text-slate-700", className)}>
      {children}
      {required && <span className="ml-0.5 text-red-500">*</span>}
    </label>
  );
}

const field = "h-10 w-full rounded-lg border border-slate-300 bg-white px-3 text-sm text-slate-800 outline-none transition placeholder:text-slate-400 focus:border-brand-500 focus:ring-2 focus:ring-brand-500/20 disabled:bg-slate-50 disabled:text-slate-500";
export const Input = forwardRef<HTMLInputElement, InputHTMLAttributes<HTMLInputElement>>(({ className, ...p }, ref) => <input ref={ref} className={cn(field, className)} {...p} />);
Input.displayName = "Input";
export const Select = forwardRef<HTMLSelectElement, SelectHTMLAttributes<HTMLSelectElement>>(({ className, ...p }, ref) => <select ref={ref} className={cn(field, "pr-8", className)} {...p} />);
Select.displayName = "Select";
export const Textarea = forwardRef<HTMLTextAreaElement, TextareaHTMLAttributes<HTMLTextAreaElement>>(({ className, ...p }, ref) => (
  <textarea ref={ref} className={cn(field, "h-auto min-h-[76px] py-2", className)} {...p} />
));
Textarea.displayName = "Textarea";

export function Field({ label, required, children, hint, className }: { label: ReactNode; required?: boolean; children: ReactNode; hint?: ReactNode; className?: string }) {
  return (
    <div className={className}>
      <Label required={required}>{label}</Label>
      {children}
      {hint && <p className="mt-1 text-xs text-slate-500">{hint}</p>}
    </div>
  );
}

export function Switch({ checked, onChange, disabled, label }: { checked: boolean; onChange: (v: boolean) => void; disabled?: boolean; label?: string }) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      aria-label={label}
      disabled={disabled}
      onClick={() => onChange(!checked)}
      className={cn("relative inline-flex h-6 w-11 shrink-0 items-center rounded-full transition-colors disabled:opacity-50", checked ? "bg-emerald-500" : "bg-slate-300")}
    >
      <span className={cn("inline-block size-5 rounded-full bg-white shadow transition-transform", checked ? "translate-x-[22px]" : "translate-x-0.5")} />
    </button>
  );
}

export function Dialog({ open, onClose, title, children, footer, size = "md", icon }: { open: boolean; onClose: () => void; title: ReactNode; children: ReactNode; footer?: ReactNode; size?: "sm" | "md" | "lg"; icon?: ReactNode }) {
  useEffect(() => {
    if (!open) return;
    const h = (e: KeyboardEvent) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", h);
    return () => window.removeEventListener("keydown", h);
  }, [open, onClose]);
  if (!open) return null;
  return (
    <div className="fixed inset-0 z-50 flex items-end justify-center bg-navy-950/40 p-0 backdrop-blur-[2px] sm:items-center sm:p-4" onMouseDown={onClose}>
      <div
        role="dialog"
        aria-modal="true"
        onMouseDown={(e) => e.stopPropagation()}
        className={cn("flex max-h-[92vh] w-full flex-col rounded-t-2xl bg-white shadow-2xl sm:rounded-2xl", size === "sm" ? "sm:max-w-md" : size === "md" ? "sm:max-w-xl" : "sm:max-w-3xl")}
      >
        <div className="flex items-center justify-between gap-3 border-b border-slate-100 px-5 py-4">
          <div className="flex items-center gap-2.5">
            {icon && <span className="text-brand-600 [&_svg]:size-5">{icon}</span>}
            <h3 className="text-base font-bold text-navy-900">{title}</h3>
          </div>
          <button onClick={onClose} className="rounded-md p-1 text-slate-400 hover:bg-slate-100 hover:text-slate-600" aria-label="Close">
            <X className="size-5" />
          </button>
        </div>
        <div className="flex-1 overflow-y-auto px-5 py-4">{children}</div>
        {footer && <div className="flex flex-wrap justify-end gap-2 border-t border-slate-100 px-5 py-3.5">{footer}</div>}
      </div>
    </div>
  );
}

export function Tabs<T extends string>({ value, onChange, items }: { value: T; onChange: (v: T) => void; items: { value: T; label: ReactNode; icon?: ReactNode; count?: number }[] }) {
  return (
    <div className="no-print flex gap-1 overflow-x-auto rounded-xl border border-slate-200 bg-white p-1">
      {items.map((it) => (
        <button
          key={it.value}
          onClick={() => onChange(it.value)}
          className={cn(
            "flex shrink-0 items-center gap-2 rounded-lg px-3.5 py-2 text-sm font-semibold transition-colors [&_svg]:size-4",
            value === it.value ? "bg-navy-900 text-white" : "text-slate-600 hover:bg-slate-100",
          )}
        >
          {it.icon}
          {it.label}
          {it.count !== undefined && <span className={cn("rounded-full px-1.5 text-xs", value === it.value ? "bg-white/20" : "bg-slate-100")}>{it.count}</span>}
        </button>
      ))}
    </div>
  );
}

export function Empty({ icon, title, children }: { icon?: ReactNode; title: string; children?: ReactNode }) {
  return (
    <div className="flex flex-col items-center justify-center gap-2 px-4 py-10 text-center">
      {icon && <div className="rounded-full bg-slate-100 p-3 text-slate-400 [&_svg]:size-6">{icon}</div>}
      <p className="font-semibold text-slate-700">{title}</p>
      {children && <div className="text-sm text-slate-500">{children}</div>}
    </div>
  );
}

export function Alert({ tone = "blue", title, children, icon, className }: { tone?: "blue" | "amber" | "red" | "green"; title?: ReactNode; children?: ReactNode; icon?: ReactNode; className?: string }) {
  const cls = { blue: "border-brand-100 bg-brand-50 text-brand-700", amber: "border-amber-200 bg-amber-50 text-amber-800", red: "border-red-200 bg-red-50 text-red-700", green: "border-emerald-200 bg-emerald-50 text-emerald-700" }[tone];
  return (
    <div className={cn("flex gap-2.5 rounded-xl border px-4 py-3 text-sm", cls, className)}>
      {icon && <span className="mt-0.5 shrink-0 [&_svg]:size-4">{icon}</span>}
      <div className="min-w-0">
        {title && <p className="font-semibold">{title}</p>}
        {children && <div className={cn(title && "mt-0.5", "opacity-90")}>{children}</div>}
      </div>
    </div>
  );
}

export function PageHeader({ title, subtitle, actions, icon }: { title: string; subtitle?: ReactNode; actions?: ReactNode; icon?: ReactNode }) {
  return (
    <div className="mb-5 flex flex-wrap items-end justify-between gap-3">
      <div className="flex items-center gap-3">
        {icon && <div className="hidden rounded-xl bg-brand-50 p-2.5 text-brand-600 sm:block [&_svg]:size-6">{icon}</div>}
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-navy-900 sm:text-[28px]">{title}</h1>
          {subtitle && <p className="mt-0.5 text-sm text-slate-500">{subtitle}</p>}
        </div>
      </div>
      {actions && <div className="no-print flex flex-wrap gap-2">{actions}</div>}
    </div>
  );
}

/** YES / NO segmented control preserving the paper form's two options plus "not answered". */
export function YesNoToggle({ value, onChange, disabled }: { value: "YES" | "NO" | null; onChange: (v: "YES" | "NO" | null) => void; disabled?: boolean }) {
  return (
    <div className="inline-flex overflow-hidden rounded-lg border border-slate-300 bg-white">
      {(["YES", "NO"] as const).map((v) => (
        <button
          key={v}
          type="button"
          disabled={disabled}
          aria-pressed={value === v}
          onClick={() => onChange(value === v ? null : v)}
          className={cn(
            "min-w-16 px-4 py-2 text-sm font-bold transition-colors disabled:opacity-60",
            v === "NO" && "border-l border-slate-300",
            value === v ? (v === "YES" ? "bg-emerald-600 text-white" : "bg-red-600 text-white") : "text-slate-600 hover:bg-slate-50",
          )}
        >
          {v}
        </button>
      ))}
    </div>
  );
}
